private List<List<Integer>> adj;
private int cuts;

public int evenForest(int n, int[][] edges) {
    adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    cuts = 0;
    dfs(1, 0);                       // root at 1, no parent (0)
    return cuts;
}

private int dfs(int u, int parent) {
    int size = 1;
    for (int v : adj.get(u)) {
        if (v != parent) {           // skip the edge back to the parent
            size += dfs(v, u);
        }
    }
    if (u != 1 && size % 2 == 0) {   // even subtree, not the root → cuttable
        cuts++;
    }
    return size;
}

