public int evenForest(int n, int[][] edges) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    int[] parent = new int[n + 1];
    int[] order = new int[n];
    int idx = 0;
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(1);
    parent[1] = 0;
    while (!stack.isEmpty()) {            // iterative DFS, no stack overflow
        int u = stack.pop();
        order[idx++] = u;
        for (int v : adj.get(u)) {
            if (v != parent[u]) {
                parent[v] = u;
                stack.push(v);
            }
        }
    }
    int[] size = new int[n + 1];
    Arrays.fill(size, 1);
    int cuts = 0;
    for (int i = n - 1; i >= 0; i--) {    // reverse order = post-order
        int u = order[i];
        if (u != 1 && size[u] % 2 == 0) cuts++;
        size[parent[u]] += size[u];       // parent[1]=0 → size[0], harmless
    }
    return cuts;
}

